INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N030-14','CN0093','S030-12','B塔三相分离器采购线索','采购项目名及索引','ZHY-Y111303，采购结果索引；转载列成交南京中衡元环保科技有限公司，主站打开重定向。不可依据三相分离器直接认定UASB/EGSB、膜或实际运行；采购者集团南化，具体资产归属厂区须核。','WEB_SECONDARY','公开正文/转载摘录；非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N030-15','CN0093','S030-13','B塔另标段','标题及采购索引','研究院催化剂事业部废水处理B塔1112W1询比采购结果，2026-11；不将1112W1解释成设计参数或处理量。','WEB_SECONDARY','公开正文/转载摘录；非原件归档','2026-11-27');
